void hash1::thread_hdltv_gen() {
    const char* dump_tv = std::getenv("AP_WRITE_TV");
    if (!(dump_tv && string(dump_tv) == "on")) return;

    wait();

    mHdltvinHandle << "[ " << endl;
    mHdltvoutHandle << "[ " << endl;
    int ap_cycleNo = 0;
    while (1) {
        wait();
        const char* mComma = ap_cycleNo == 0 ? " " : ", " ;
        mHdltvinHandle << mComma << "{"  <<  " \"ap_rst\" :  \"" << ap_rst.read() << "\" ";
        mHdltvoutHandle << mComma << "{"  <<  " \"input_V_address0\" :  \"" << input_V_address0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_ce0\" :  \"" << input_V_ce0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_d0\" :  \"" << input_V_d0.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"input_V_q0\" :  \"" << input_V_q0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_we0\" :  \"" << input_V_we0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_address1\" :  \"" << input_V_address1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_ce1\" :  \"" << input_V_ce1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_d1\" :  \"" << input_V_d1.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"input_V_q1\" :  \"" << input_V_q1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"input_V_we1\" :  \"" << input_V_we1.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"bitlength\" :  \"" << bitlength.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_address0\" :  \"" << outputlocation_V_address0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_ce0\" :  \"" << outputlocation_V_ce0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_d0\" :  \"" << outputlocation_V_d0.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"outputlocation_V_q0\" :  \"" << outputlocation_V_q0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_we0\" :  \"" << outputlocation_V_we0.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_address1\" :  \"" << outputlocation_V_address1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_ce1\" :  \"" << outputlocation_V_ce1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_d1\" :  \"" << outputlocation_V_d1.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"outputlocation_V_q1\" :  \"" << outputlocation_V_q1.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"outputlocation_V_we1\" :  \"" << outputlocation_V_we1.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"ap_start\" :  \"" << ap_start.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_done\" :  \"" << ap_done.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_ready\" :  \"" << ap_ready.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_idle\" :  \"" << ap_idle.read() << "\" ";
        mHdltvinHandle << "}" << std::endl;
        mHdltvoutHandle << "}" << std::endl;
        ap_cycleNo++;
    }
}

